import os, sys, fcntl, termios, struct, select, subprocess, json, hashlib
import pty as _pty
maps = json.load(open('/tmp/sdhelpwork/maps.json'))
def ident(data, kind='s'):
    h = hashlib.md5(data).hexdigest(); w = maps[kind].get(h)
    return f"[{w[0]}..{w[-1]}]" if w else f"UNKNOWN({h[:8]},{len(data)}b)"

def mkpty(cols, rows=24):
    m, s = _pty.openpty()
    fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    return m, s

def run(fdspec, env_extra=None, args=('-h',)):
    """fdspec: {0: cols_or_None, 1: ..., 2: ...}  None => pipe"""
    env = dict(os.environ); env.pop('COLUMNS', None)
    if env_extra: env.update(env_extra)
    masters=[]; child={}
    for fd in (0,1,2):
        c = fdspec.get(fd)
        if c is None:
            r,w = os.pipe()
            child[fd] = r if fd==0 else w
            masters.append(('pipe', w if fd==0 else r, child[fd]))
        else:
            m,s = mkpty(c)
            child[fd] = s
            masters.append(('pty', m, s))
    p = subprocess.Popen(['sd', *args], executable='/workspace/executable',
                         stdin=child[0], stdout=child[1], stderr=child[2],
                         env=env, preexec_fn=os.setsid, close_fds=True)
    for kind, mfd, sfd in masters: os.close(sfd)
    readfds=[]
    for i,(kind,mfd,sfd) in enumerate(masters):
        if i==0 and kind=='pipe': os.close(mfd)
        elif i==0 and kind=='pty': readfds.append(mfd)
        else: readfds.append(mfd)
    data=b''
    fds=list(set(readfds))
    while fds:
        r,_,_ = select.select(fds,[],[],5)
        if not r: break
        for fd in r:
            try: chunk=os.read(fd,65536)
            except OSError: chunk=b''
            if not chunk: fds.remove(fd); continue
            data+=chunk
    p.wait()
    for fd in set(readfds):
        try: os.close(fd)
        except OSError: pass
    return data.replace(b'\r\n', b'\n')
